import{_ as o,o as t,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Documents — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Documents — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/documents"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Documents — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/documents"}]]},"headers":[],"relativePath":"deployment/documents.md","filePath":"deployment/documents.md","lastUpdated":1787351200000}'),r={name:"deployment/documents.md"};function a(s,e,d,l,c,m){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="documents-—-production-guide" tabindex="-1">Documents — Production Guide <a class="header-anchor" href="#documents-—-production-guide" aria-label="Permalink to &quot;Documents — Production Guide&quot;">​</a></h1><p>Full go-live audit / checklist: <a href="./documents-production-readiness">Documents production readiness</a>.</p><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>documents</code></li><li>Category: <code>operations</code> (<strong>Operations</strong>), <code>category_sort_order = 40</code></li><li><strong>Free Marketplace opt-in</strong> module (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code>, <code>sort_order = 85</code>, version <strong>1.1.0</strong></li><li><strong>Hard</strong> <code>module_dependencies</code> row: Documents → Storage (<code>is_optional = false</code>)</li><li>New workspaces receive only <strong>Leads</strong> + <strong>Tasks</strong> (+ ToDos) by default; enable Storage, then Documents from Marketplace</li><li>To flip billable later: Central → Modules → Documents → set <code>is_billable</code> + prices via existing Update Module API (no new Central UI)</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create (Central tenant create or public register):</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules (<strong>Leads</strong>, <strong>Tasks</strong>, <strong>ToDos</strong>)</li><li>Operators enable <strong>Storage</strong> from Marketplace (or receive it via Team Chat companion install / grandfather)</li><li>Operators enable <strong>Documents</strong> from Marketplace (free / non-billable; install blocked without Storage)</li><li>Tenant permissions include <code>documents.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><p>No stage seeder — categories are tenant-managed. Files land on <code>FILESYSTEM_UPLOADS_DISK</code> under <code>tenants/{id}/documents/…</code>.</p><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Documents permissions for <strong>existing</strong> workspaces ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code>. Do <strong>not</strong> re-seed roles or rely on login/dashboard to repair RBAC.</p><p>On large tenant fleets, run migrate in a maintenance window (or raise PHP <code>max_execution_time</code>). The synchronizer grants missing links only and swallows concurrent <code>role_has_permissions</code> unique races.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>document_created</code>, <code>document_updated</code>, <code>document_deleted</code>, <code>document_restored</code>, <code>document_force_deleted</code></li><li>Spatie activity log names: <code>documents</code>, <code>document-categories</code></li><li>Storage used bytes include active <code>documents.size_bytes</code></li><li>Soft-deleted document objects remain on disk until <strong>force delete</strong> or workspace <strong>trash retention</strong> purge (<code>trash:purge-expired</code>, Settings → General → trash retention)</li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate tables (<code>document_categories</code>, <code>documents</code>)</li><li>Register the <code>documents</code> catalog module (migration, not seeder) as free opt-in under <code>operations</code></li><li>Register hard dependency Documents → Storage (<code>module_dependencies</code>)</li><li>Confirm <code>module:documents</code> + <code>documents.*</code> permissions on target roles (permission sync migration)</li><li>Confirm catalog version <strong>1.1.0</strong> (<code>110000</code> bump)</li><li>Confirm Storage is entitled before Documents smoke</li><li>Confirm <code>trash:purge-expired</code> is scheduled (removes expired soft-deleted documents <strong>and</strong> disk objects)</li><li>Deploy frontend (Documents nav item, list/form/categories; multipart update via POST; bulk delete toolbar)</li><li>Smoke: <ul><li>Create a <strong>new</strong> workspace → install Storage → install Documents</li><li>Confirm Documents install fails when Storage is missing</li><li>Upload / categorize / download a file</li><li>Soft delete → used bytes drop → restore → used bytes return</li><li>Restore blocked when over quota</li><li>Bulk soft delete on Active list; bulk force delete on Deleted only</li><li>Force delete removes the object</li><li>Soft-delete category blocked while documents still use it</li></ul></li></ol><h2 id="roadmap-context" tabindex="-1">Roadmap context <a class="header-anchor" href="#roadmap-context" aria-label="Permalink to &quot;Roadmap context&quot;">​</a></h2><p>Documents ships as free Operations Marketplace opt-in <strong>v1.1.0</strong> (shipped) with hard Storage dependency. Soft record links and nested folders remain deferred — see <a href="/architecture/module-dependencies">module-dependencies.md</a> and <a href="/getting-started/product-roadmap">product-roadmap.md</a>.</p>',17)])])}const g=o(r,[["render",a]]);export{p as __pageData,g as default};
